    String displayName = getDisplayName();
    return displayName != null && !displayName.isEmpty();
  }

  public boolean isNoType() {
    return false;
  }

  public boolean isNoResolvedType() {
    return false;
  }

  public boolean isNoObjectType() {
    return false;
  }

